//ocr识别后调用接口赋值
function BizDataChangeCallBackAfter(fieldCode, fieldValue, index, formData) {
    debugger;
    if ("personalSupplierBackPicture" == fieldCode) {
        if(opspagev.formData.businessLicenseEndDate == "无" ||opspagev.formData.businessLicenseEndDate == "长期"){
            opspagev.formData.businessLicenseEndDate="2099-12-31";
        }
    }
    if ("business" == fieldCode) {
        console.log("ocr识别后supplierName="+opspagev.formData.supplierName);
        opspagev.hideField("businessPrompt");
        if (opspagev.formData.supplierName != "") {
            opspagev.clearValidate("supplierName");
            if( opspagev.formData.business != null && opspagev.formData.business != "" ){
                //cheerwell-add 进行天眼查数据同步逻辑
                var resultTycInfo = OPSExecInterface(ipPort + "/supplier/tycInfo", { "supplierName": opspagev.formData.supplierName }, "GET");
                console.log("天眼查接口返回数据:" + JSON.stringify(resultTycInfo));

                // var tycInfo = JSON.parse(resultTycInfo.Content)[0];
                var tycInfo = null;
                try {
                    var parsed = JSON.parse(resultTycInfo.Content);
                    // 判断解析后是否是数组并且有值
                    if (Array.isArray(parsed) && parsed.length > 0) {
                        tycInfo = parsed[0];
                    }
                } catch (e) {
                    console.log("JSON.parse 解析天眼查数据失败:", e);
                    tycInfo = null;
                }

                if(tycInfo != null){
                    console.log("tycInfo="+tycInfo.creditCode);
                    if(tycInfo.creditCode != null && tycInfo.creditCode != ""){
                        opspagev.formData.unifiedSocialCertificateCode = tycInfo.creditCode+"";
                        opspagev.clearValidate("unifiedSocialCertificateCode");
                    }
                    opspagev.formData.establishDate=tycInfo.estiblishTime;
                    //证件有效期至字段目前天眼查返回为null，使用OCR识别字段
                    if(opspagev.formData.disabledTime == "无" ||opspagev.formData.disabledTime == "长期"){
                        opspagev.formData.disabledTime="2099-12-31";
                        opspagev.formData.disabledTimeStr="长期";
                        opspagev.hideField("disabledTime");
                        opspagev.showField("disabledTimeStr");
                        opspagev.setFieldReadOnly("disabledTimeStr", true);
                    }
                    else{
                        opspagev.formData.disabledTimeStr="";
                        opspagev.hideField("disabledTimeStr");
                        opspagev.showField("disabledTime");
                    }
                    //opspagev.formData.disabledTime=tycInfo.toTime;
                    if(tycInfo.legalPersonName != null && tycInfo.legalPersonName != ""){
                        opspagev.formData.legal=tycInfo.legalPersonName;
                        opspagev.clearValidate("legal");
                    }
                    if(tycInfo.phoneNumber != null && tycInfo.phoneNumber != "" ){
                        opspagev.formData.companyPhone=tycInfo.phoneNumber+"";
                    }else{
                        opspagev.formData.companyPhone="";
                    }
                    if( tycInfo.companyOrgType != null &&  tycInfo.companyOrgType >= 0){
                        opspagev.formData.companyNature=tycInfo.companyOrgType+"";
                        opspagev.formData.companyNatureExtend=tycInfo.companyNatureExtend;
                    }else{
                        opspagev.formData.companyNature="";
                    }
                    if(tycInfo.industry != null && tycInfo.industry >= 0){
                        opspagev.formData.industry=tycInfo.industry+"";
                    }else{
                        opspagev.formData.industry="";
                    }
                    if(tycInfo.regCapital > 0){
                        opspagev.formData.capital=tycInfo.regCapital;
                    }else{
                        opspagev.formData.capital=0;
                    }
                    if(tycInfo.regCapitalCurrency != null && tycInfo.regCapitalCurrency >= 0){
                        opspagev.formData.currency=tycInfo.regCapitalCurrency+"";
                    }
                    opspagev.formData.countrySelection=0+"";//默认国内
                    opspagev.hideField("detailAddress");
                    opspagev.showField("address");
                    //地址处理:省市区都有code，回填省市区+详细地址，否则省市区不回填，只回填详细地址
                    if(tycInfo.ProvinceCode>0 && tycInfo.CityCode>0 && tycInfo.AreaCode>0){
                        if(tycInfo.regLocation != null && tycInfo.regLocation != ""){
                            opspagev.formData.address = { "ProvinceCode": tycInfo.ProvinceCode,"CityCode": tycInfo.CityCode,"AreaCode": tycInfo.AreaCode,"ProvinceName": tycInfo.ProvinceName, "CityName": tycInfo.CityName, "AreaName": tycInfo.AreaName, "StreetCode": "", "StreetName": "", "DetailAddress": tycInfo.regLocation, "FullAddress": tycInfo.regLocation };
                            opspagev.formData.detailAddress=tycInfo.regLocation;
                        }else{
                            opspagev.formData.address = { "ProvinceCode": tycInfo.ProvinceCode,"CityCode": tycInfo.CityCode,"AreaCode": tycInfo.AreaCode,"ProvinceName": tycInfo.ProvinceName, "CityName": tycInfo.CityName, "AreaName": tycInfo.AreaName, "StreetCode": "", "StreetName": "", "DetailAddress": "", "FullAddress": "" };
                        }
                    }else{
                        if(tycInfo.regLocation != null && tycInfo.regLocation != ""){
                            opspagev.formData.address = {  "DetailAddress": tycInfo.regLocation, "FullAddress": tycInfo.regLocation };
                            opspagev.formData.detailAddress=tycInfo.regLocation;
                        }
                    }
                    if(tycInfo.websiteList != null && tycInfo.websiteList != "" ){
                        opspagev.formData.webSite=tycInfo.websiteList;
                    }else{
                        opspagev.formData.webSite="";
                    }
                    if(tycInfo.businessScope != null && tycInfo.businessScope != ""){
                        opspagev.formData.businessScope=tycInfo.businessScope;
                        opspagev.clearValidate("businessScope");
                    }
                    console.log("天眼查同步数据结构:" + JSON.stringify(opspagev.formData));
                }
            }
        }
        //日期校验
        if (!(/^\\d{4}\-\\d{2}\-\\d{2}$/).test(opspagev.formData.establishDate)) {
            opspagev.formData.establishDate = ""
        }
        if (!(/^\\d{4}\-\\d{2}\-\\d{2}$/).test(opspagev.formData.disabledTime)) {
            opspagev.formData.disabledTime = ""
        }
    }
    if ("passportPhoto" == fieldCode || "passPhoto" == fieldCode || "twpassPhoto" == fieldCode|| "certificatesPhoto" == fieldCode) {
        if (opspagev.formData.sexCopy == "女/F") {
            opspagev.formData.sex = "1"
        } else if (opspagev.formData.sexCopy == "男/M") {
            opspagev.formData.sex = "0"
        } else if (opspagev.formData.sexCopy == "女") {
            opspagev.formData.sex = "1"
        } else if (opspagev.formData.sexCopy == "男") {
            opspagev.formData.sex = "0"
        }

        if (top.OPSThirdPartyTokenInfo != null && top.OPSThirdPartyTokenInfo != "") {
            setTimeout(() => { opspagev.formData.supplierName = top.OPSThirdPartyTokenInfo.supplierName }, 10);
            setTimeout(() => { opspagev.formData.name = top.OPSThirdPartyTokenInfo.supplierName }, 10);
        }
        if (opspagev.formData.name != null && opspagev.formData.name != "") {
            setTimeout(() => { opspagev.formData.accountName = opspagev.formData.name }, 12)
        }

        if ("passPhoto" == fieldCode || "twpassPhoto" == fieldCode) {
            if (opspagev.formData.passPhotoTime != null && opspagev.formData.passPhotoTime != "") {
                var time = opspagev.formData.passPhotoTime.split("-");
                opspagev.formData.businessLicenseBeginDate = time[0].replace(".", "-").replace(".", "-");
                opspagev.formData.businessLicenseEndDate = time[1].replace(".", "-").replace(".", "-");
            }
        }
    }
    if ("accountLicensePicture" == fieldCode) {
        if (opspagev.formData.accountNumber != "" && opspagev.formData.accountNumber != null) {
            var accountNumber = opspagev.formData.accountNumber;
            opspagev.formData.accountNumber = accountNumber.split(" ").join("");
        }
    }

    if (fieldCode == "enterpriseBankform_accountLicensePicture") {
        if (formData.accountNumber != "" && formData.accountNumber != null) {
            formData.accountNumber = formData.accountNumber.split(" ").join("");
        }
    }

    if ("disabledTime" == fieldCode) {
        if(opspagev.formData.disabledTime == "2099-12-31"){
            opspagev.formData.disabledTime="2099-12-31";
            opspagev.formData.disabledTimeStr="长期";
            opspagev.hideField("disabledTime");
            opspagev.showField("disabledTimeStr");
            opspagev.setFieldReadOnly("disabledTimeStr", true);
        }
    }
}

