// 校验是否能提交
function custAppValidate() {
    debugger;
    var accountTypeRepeat = 0;
    var supplierType = opspagev.formData.supplierType + "";

    for (var i = 0; i < opspagev.formData.enterpriseBankform.length; i++) {
        var accountType = opspagev.formData.enterpriseBankform[i].accountType;//账户类型
        if (accountType == 0){
            accountTypeRepeat = accountTypeRepeat + 1;
        }
    }

    if ("0" == supplierType) {
        if (accountTypeRepeat > 1){
            return "基本账户只能有一个，请修改账户类型！";
        }
    }

    let supplierContact = opspagev.formData.supplierContact;
    for (let i = 0; i < supplierContact.length; i++) {
        opspagev.$refs.supplierContactSubTable.$refs.subTableForm[i].rules.contactPhone.splice(1, 1);
    }
    return "";

}


