function enterpriseBankform_SaveCallback(formData,index){
    if (formData &&
        formData.branchBank &&
        formData.branchBank.dataList &&
        formData.branchBank.dataList.length > 0 &&
        formData.bank &&
        formData.bank.dataList &&
        formData.bank.dataList.length > 0) {

        let bankName1 = formData.branchBank.dataList[0].bankName;
        let bankName2 = formData.bank.dataList[0].bankName;

        if (bankName1 !== bankName2) {
            return "开户银行与银行分行不匹配，请重新选择"
        }
    }
}

